   106→/**
   107→ * Fetch RTN dashboard data for all teams in a competition config
   108→ * Returns an object with team1, team2, etc. keys containing RTN data
   109→ * Also merges headshots from Firebase teamsDatabase if available
   110→ */
   111→async function enrichTeamsWithRTN(config, gender = 'womens') {
   112→  const teamData = {};
   113→  const teamNames = [
   114→    config.team1Name,
   115→    config.team2Name,
   116→    config.team3Name,
   117→    config.team4Name,
   118→    config.team5Name,
   119→    config.team6Name,
   120→  ].filter(Boolean); // Remove empty team names
   121→
   122→  // Fetch RTN team dashboards and Firebase headshots in parallel
   123→  const [rtnResults, firebaseHeadshots] = await Promise.all([
   124→    Promise.allSettled(teamNames.map(name => getTeamDashboard(name, gender))),
   125→    getFirebaseHeadshots()
   126→  ]);
   127→
   128→  rtnResults.forEach((result, index) => {
   129→    const teamKey = `team${index + 1}`;
   130→    if (result.status === 'fulfilled' && result.value) {
   131→      const dashboard = result.value;
   132→
   133→      // Extract and normalize the data we care about
   134→      teamData[teamKey] = {
   135→        rtnId: dashboard.info?.team_id || null,
   136→        fetchedAt: new Date().toISOString(),
   137→
   138→        // Coaching staff (filtered to coaches only)
   139→        coaches: (dashboard.staff || [])
   140→          .filter(s => s.position?.toLowerCase().includes('coach'))
   141→          .map(s => ({
   142→            id: s.id,
   143→            firstName: s.first_name?.trim() || '',
   144→            lastName: s.last_name?.trim() || '',
   145→            fullName: `${s.first_name?.trim() || ''} ${s.last_name?.trim() || ''}`.trim(),
   146→            position: s.position,
   147→            imageUrl: s.image_url ? `https://www.roadtonationals.com/images/staff/${s.image_url}` : null,
   148→          }))
   149→          .sort((a, b) => {
   150→            if (a.position?.toLowerCase().includes('head')) return -1;
   151→            if (b.position?.toLowerCase().includes('head')) return 1;
   152→            return 0;
   153→          }),
   154→
   155→        // Rankings
   156→        rankings: dashboard.ranks ? (gender === 'womens' ? {
   157→          vault: dashboard.ranks.vault ? parseInt(dashboard.ranks.vault) : null,
   158→          bars: dashboard.ranks.bars ? parseInt(dashboard.ranks.bars) : null,
   159→          beam: dashboard.ranks.beam ? parseInt(dashboard.ranks.beam) : null,
   160→          floor: dashboard.ranks.floor ? parseInt(dashboard.ranks.floor) : null,
   161→          team: dashboard.ranks.team ? parseInt(dashboard.ranks.team) : null,
   162→        } : {
   163→          floor: dashboard.ranks.floor ? parseInt(dashboard.ranks.floor) : null,
   164→          pommel: dashboard.ranks.phorse ? parseInt(dashboard.ranks.phorse) : null,
   165→          rings: dashboard.ranks.rings ? parseInt(dashboard.ranks.rings) : null,
   166→          vault: dashboard.ranks.vault ? parseInt(dashboard.ranks.vault) : null,
   167→          pBars: dashboard.ranks.pbars ? parseInt(dashboard.ranks.pbars) : null,
   168→          hBar: dashboard.ranks.highbar ? parseInt(dashboard.ranks.highbar) : null,
   169→          team: dashboard.ranks.team ? parseInt(dashboard.ranks.team) : null,
   170→        }) : null,
   171→
   172→        // Team scoring stats (from RTN 'test' field)
   173→        stats: dashboard.test ? {
   174→          average: dashboard.test.ave || null,
   175→          high: dashboard.test.high || null,
   176→          rqs: dashboard.test.rqs || null, // Ranking Qualifying Score
   177→        } : null,
   178→
   179→        // Roster - merge with Firebase headshots by matching athlete names
   180→        // Uses lookupHeadshot which tries multiple normalized keys for flexible matching
   181→        roster: (dashboard.roster || []).map(r => {
   182→          const firstName = r.fname?.trim() || '';
   183→          const lastName = r.lname?.trim() || '';
   184→          const fullName = `${firstName} ${lastName}`.trim();
   185→          const headshotUrl = lookupHeadshot(firebaseHeadshots, firstName, lastName);
   186→
   187→          return {
   188→            id: r.id,
   189→            rtnId: r.id ? String(r.id) : null, // RTN athlete ID for stats joining
   190→            firstName,
   191→            lastName,
   192→            fullName,
   193→            hometown: r.hometown || '',
   194→            year: r.school_year ? parseInt(r.school_year) : null,
   195→            headshotUrl, // Merged from Firebase teamsDatabase using flexible matching
   196→          };
   197→        }),
   198→
   199→        // Social links
   200→        links: (() => {
   201→          const links = {};
   202→          for (const link of (dashboard.links || [])) {
   203→            const type = link.tax_value?.toLowerCase() || '';
   204→            if (type.includes('facebook')) links.facebook = link.link;
   205→            else if (type.includes('twitter')) links.twitter = link.link;
   206→            else if (type.includes('instagram')) links.instagram = link.link;
   207→            else if (type.includes('official')) links.officialSite = link.link;
   208→          }
   209→          return links;
   210→        })(),
   211→
   212→        // Schedule
   213→        schedule: (dashboard.meets || []).map(m => ({
   214→          meetId: m.meet_id,
   215→          date: m.meet_date,
   216→          opponent: m.opponent,
   217→          description: m.meet_desc || '',
   218→          home: m.home === 'H',
   219→          away: m.home === 'A',
   220→          score: m.team_score ? parseFloat(m.team_score) : null,
   221→        })),
   222→      };
   223→    }
   224→  });
   225→
   226→  // Persist RTN IDs to teamsDatabase for use by stats service
   227→  // This stores team-level and athlete-level RTN IDs in the shared store
   228→  for (let i = 0; i < teamNames.length; i++) {
   229→    const teamKey = `team${i + 1}`;
   230→    const data = teamData[teamKey];
   231→    if (!data?.rtnId) continue;
   232→
   233→    const teamDbKey = buildTeamKey(teamNames[i], gender);
   234→    if (!teamDbKey) continue;
   235→
   236→    try {
   237→      // Store team RTN ID (only if not already set or different)
   238→      const teamRtnIdRef = ref(db, `teamsDatabase/teams/${teamDbKey}/rtnId`);
   239→      const existingRtnId = await get(teamRtnIdRef);
   240→      if (!existingRtnId.exists() || existingRtnId.val() !== data.rtnId) {
   241→        await set(teamRtnIdRef, data.rtnId);
   242→        console.log(`[enrichTeamsWithRTN] Stored RTN ID ${data.rtnId} for team ${teamDbKey}`);
   243→      }
   244→
   245→      // Store per-athlete RTN IDs in teamsDatabase/headshots/{name}/rtnId
   246→      if (data.roster && Array.isArray(data.roster)) {
   247→        for (const athlete of data.roster) {
   248→          if (!athlete.rtnId || !athlete.fullName) continue;
   249→          const headshotKey = normalizeName(athlete.fullName).replace(/\s+/g, '_');
   250→          if (!headshotKey) continue;
   251→          try {
   252→            const athleteRtnIdRef = ref(db, `teamsDatabase/headshots/${headshotKey}/rtnId`);
   253→            const existingAthleteRtnId = await get(athleteRtnIdRef);
   254→            if (!existingAthleteRtnId.exists() || String(existingAthleteRtnId.val()) !== athlete.rtnId) {
   255→              await set(athleteRtnIdRef, athlete.rtnId);
   256→            }
   257→          } catch (err) {
   258→            console.warn(`[enrichTeamsWithRTN] Failed to store RTN ID for athlete ${athlete.fullName}:`, err.message);
   259→          }
   260→        }
   261→      }
   262→    } catch (err) {
   263→      console.warn(`[enrichTeamsWithRTN] Failed to store RTN ID for team ${teamDbKey}:`, err.message);
   264→    }
   265→  }
   266→
   267→  return teamData;
   268→}
