   292→/**
   293→ * Check if we're in a secure (production) context
   294→ * @returns {boolean}
   295→ */
   296→function isSecureContext() {
   297→  return typeof window !== 'undefined' &&
   298→    (window.location.protocol === 'https:' || window.location.hostname === 'commentarygraphic.com');
   299→}
