   301→/**
   302→ * Check VM status by fetching /api/status endpoint
   303→ * In production (HTTPS), routes through the coordinator to avoid Mixed Content errors.
   304→ * In development (HTTP), calls the VM directly.
   305→ *
   306→ * @param {string} vmAddress - The VM address (host:port format, no protocol)
   307→ * @param {number} timeout - Timeout in milliseconds (default 5000)
   308→ * @param {string} compId - Competition ID (required for production routing)
   309→ * @returns {Promise<{online: boolean, obsConnected?: boolean, noVm?: boolean, error?: string}>}
   310→ */
   311→export async function checkVmStatus(vmAddress, timeout = 5000, compId = null) {
   312→  // In production (HTTPS), route through coordinator to avoid Mixed Content
   313→  if (isSecureContext() && compId) {
   314→    const controller = new AbortController();
   315→    const timeoutId = setTimeout(() => controller.abort(), timeout);
   316→
   317→    try {
   318→      const response = await fetch(`https://api.commentarygraphic.com/api/vm/${compId}/status`, {
   319→        signal: controller.signal,
   320→        headers: { 'Accept': 'application/json' },
   321→      });
   322→
   323→      clearTimeout(timeoutId);
   324→
   325→      if (!response.ok) {
   326→        return { online: false, error: `HTTP ${response.status}` };
   327→      }
   328→
   329→      return await response.json();
   330→    } catch (err) {
   331→      clearTimeout(timeoutId);
   332→      if (err.name === 'AbortError') {
   333→        return { online: false, error: 'Request timed out' };
   334→      }
   335→      return { online: false, error: err.message || 'Connection failed' };
   336→    }
   337→  }
   338→
   339→  // Development mode: call VM directly
   340→  if (!isValidVmAddress(vmAddress)) {
   341→    return { online: false, error: 'Invalid VM address format' };
   342→  }
   343→
   344→  const controller = new AbortController();
   345→  const timeoutId = setTimeout(() => controller.abort(), timeout);
   346→
   347→  try {
   348→    const response = await fetch(`http://${vmAddress}/api/status`, {
   349→      signal: controller.signal,
   350→      headers: {
   351→        'Accept': 'application/json',
   352→      },
   353→    });
   354→
   355→    clearTimeout(timeoutId);
   356→
   357→    if (!response.ok) {
   358→      return { online: false, error: `HTTP ${response.status}` };
   359→    }
   360→
   361→    const data = await response.json();
   362→
   363→    return {
   364→      online: true,
   365→      obsConnected: data.obsConnected || false,
   366→    };
   367→  } catch (err) {
   368→    clearTimeout(timeoutId);
   369→
   370→    if (err.name === 'AbortError') {
   371→      return { online: false, error: 'Request timed out' };
   372→    }
   373→
   374→    return { online: false, error: err.message || 'Connection failed' };
   375→  }
   376→}
