  fetchTeamDashboard,
  getTeamDashboard,
  getCoachingStaff,
  getTeamSocialLinks,
  getTeamRankings,
  getRtnRoster,
  getTeamSchedule,

  // Schedule
  getWeeklySchedule,
  getYearWeeks,
};

