   320→function parseScore(val) {
   321→  if (val === null || val === undefined || val === '' || val === '0.0000' || val === 0) return null;
   322→  const num = typeof val === 'number' ? val : parseFloat(val);
   323→  if (isNaN(num)) return null;
   324→  if (num < 0) return null; // Negative = exhibition/scratch
   325→  return Math.round(num * 10000) / 10000;
