   366→  if (Object.keys(events).length === 0) return null;
   367→
   368→  return { labels, events };
   369→}
   370→
   371→/**
   372→ * Normalize MVP data.
   373→ * Raw shape: array of athlete objects with sum fields (vsum, ubsum, etc.) and gid.
   374→ *
   375→ * @param {Array} raw - Raw RTN MVP response
   376→ * @param {string} gender - "mens" or "womens"
   377→ * @returns {Array|null} Array of { rtnId, firstName, lastName, fullName, events: {...}, total }
   378→ */
   379→function normalizeMVP(raw, gender) {
   380→  if (!raw || !Array.isArray(raw) || raw.length === 0) return null;
   381→
   382→  const eventMap = getMvpEvents(gender);
   383→
   384→  return raw.map(athlete => {
   385→    const events = {};
   386→    let total = 0;
   387→
   388→    for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   389→      const score = parseScore(athlete[rtnField]);
   390→      events[stdCode] = score;
   391→      if (score !== null) total += score;
   392→    }
   393→
   394→    // Round total to 4 decimals to avoid floating-point artifacts
   395→    total = Math.round(total * 10000) / 10000;
   396→
   397→    return {
   398→      rtnId: toRtnIdString(athlete.gid),
   399→      firstName: (athlete.fname || '').trim(),
   400→      lastName: (athlete.lname || '').trim(),
   401→      fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
   402→      events,
   403→      total,
   404→    };
   405→  }).sort((a, b) => b.total - a.total);
   406→}
   407→
   408→/**
   409→ * Normalize top scores data.
   410→ * Raw shape: { data: [...top lineup entries...], max: number }
   411→ * Each entry has gymnast_id and event-named fields (vault, bars, beam, floor for women).
   412→ *
   413→ * @param {Object} raw - Raw RTN top scores response
   414→ * @param {string} gender - "mens" or "womens"
   415→ * @returns {Object|null} { theoreticalMax, scores: [...], events: { VT: [...], UB: [...], ... } }
   416→ */
   417→function normalizeTopScores(raw, gender) {
   418→  if (!raw || typeof raw !== 'object') return null;
   419→
   420→  const rawData = raw.data || raw;
   421→  if (!Array.isArray(rawData)) return null;
   422→
   423→  const eventMap = getTopScoreEvents(gender);
   424→  const theoreticalMax = parseScore(raw.max) || null;
   425→
   426→  // Group athletes by event
   427→  const events = {};
   428→  for (const stdCode of Object.values(eventMap)) {
   429→    events[stdCode] = [];
   430→  }
   431→
   432→  // Also build the flat scores array (top lineup entries)
   433→  const scores = rawData.map(entry => {
   434→    const row = {};
   435→    for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   436→      row[rtnField] = entry[rtnField] || '';
   437→    }
   438→    return row;
   439→  });
   440→
   441→  // Build per-event top athletes
   442→  for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   443→    // Collect athletes who have a score for this event
   444→    const athletesWithScores = rawData
   445→      .filter(entry => {
   446→        const score = parseScore(entry[rtnField]);
   447→        return score !== null;
   448→      })
   449→      .map(entry => ({
   450→        rtnId: toRtnIdString(entry.gymnast_id || entry.gid || entry.id),
   451→        firstName: (entry.fname || '').trim(),
   452→        lastName: (entry.lname || '').trim(),
   453→        fullName: `${(entry.fname || '').trim()} ${(entry.lname || '').trim()}`.trim(),
   454→        high: parseScore(entry[rtnField]),
   455→      }))
   456→      .sort((a, b) => (b.high || 0) - (a.high || 0));
   457→
   458→    events[stdCode] = athletesWithScores;
   459→  }
   460→
   461→  return { theoreticalMax, scores, events };
   462→}
   463→
   464→/**
   465→ * Normalize lineup data.
   466→ * Raw shape: array of athlete objects with binary meets arrays and id field.
   467→ *
   468→ * @param {Array} raw - Raw RTN lineup response
   469→ * @param {string} gender - "mens" or "womens"
   470→ * @returns {Array|null} Array of { rtnId, firstName, lastName, fullName, meets: number[], rate: number }
   471→ */
   472→function normalizeLineup(raw, gender) {
   473→  if (!raw || !Array.isArray(raw) || raw.length === 0) return null;
   474→
   475→  return raw.map(athlete => {
   476→    const meets = athlete.meets || [];
   477→    const totalMeets = meets.length;
   478→    const competed = meets.filter(m => m === 1 || m === '1').length;
   479→    const rate = totalMeets > 0 ? Math.round((competed / totalMeets) * 10000) / 10000 : 0;
   480→
   481→    return {
   482→      rtnId: toRtnIdString(athlete.id || athlete.gid),
   483→      firstName: (athlete.fname || '').trim(),
   484→      lastName: (athlete.lname || '').trim(),
   485→      fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
   486→      meets: meets.map(m => (m === 1 || m === '1') ? 1 : 0),
   487→      rate,
   488→    };
   489→  });
   490→}
   491→
   492→/**
   493→ * Normalize individual stats (highs or averages).
   494→ * Raw shape: { team: [...], ind: [...] } — NOT a flat array.
   495→ * The `ind` array contains athlete records with fields like maxv, maxub, maxbb, maxfx, maxaa (women)
   496→ * or maxfx, maxph, maxsr, maxvt, maxpb, maxhb, maxaa (men), plus gid.
   497→ *
   498→ * @param {Object} raw - Raw RTN rostermain response
   499→ * @param {string} gender - "mens" or "womens"
   500→ * @returns {Array|null} Array of { rtnId, firstName, lastName, fullName, events: { VT, UB, ... } }
   501→ */
   502→function normalizeIndividualStats(raw, gender) {
   503→  if (!raw || typeof raw !== 'object') return null;
   504→
   505→  // Handle { team, ind } structure
   506→  const athletes = raw.ind || raw;
   507→  if (!Array.isArray(athletes) || athletes.length === 0) return null;
   508→
   509→  const fieldMap = getIndividualFields(gender);
   510→
   511→  return athletes.map(athlete => {
   512→    const events = {};
   513→
   514→    for (const [rtnField, stdCode] of Object.entries(fieldMap)) {
   515→      events[stdCode] = parseScore(athlete[rtnField]);
   516→    }
   517→
   518→    return {
   519→      rtnId: toRtnIdString(athlete.gid || athlete.id),
   520→      firstName: (athlete.fname || '').trim(),
   521→      lastName: (athlete.lname || '').trim(),
   522→      fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
   523→      events,
   524→    };
   525→  });
   526→}
   527→
   528→/**
   529→ * Normalize individual highs (convenience wrapper).
   530→ * @param {Object} raw - Raw RTN rostermain/{tid}/2 response
   531→ * @param {string} gender
   532→ * @returns {Array|null}
   533→ */
   534→function normalizeIndividualHighs(raw, gender) {
   535→  return normalizeIndividualStats(raw, gender);
   536→}
   537→
   538→/**
   539→ * Normalize individual averages (convenience wrapper).
   540→ * @param {Object} raw - Raw RTN rostermain/{tid}/3 response
   541→ * @param {string} gender
   542→ * @returns {Array|null}
   543→ */
   544→function normalizeIndividualAverages(raw, gender) {
   545→  return normalizeIndividualStats(raw, gender);
   546→}
   547→
   548→/**
   549→ * Normalize team ranking from league results.
   550→ * The results endpoint returns ALL teams; we find ours by tid.
   551→ *
   552→ * Raw shape: { data: [...], schema: {...} }
   553→ * Each entry in data has: tid, rank, ave, high, rqs, conference, region, division, etc.
   554→ *
   555→ * @param {Object} raw - Raw RTN results response
   556→ * @param {string} gender - "mens" or "womens"
   557→ * @param {number|string} tid - RTN team ID to find
   558→ * @returns {Object|null} { rank, ave, high, rqs, conference, region, division }
   559→ */
   560→function normalizeTeamRanking(raw, gender, tid) {
   561→  if (!raw || typeof raw !== 'object') return null;
   562→
   563→  const results = raw.data || raw;
   564→  if (!Array.isArray(results) || results.length === 0) return null;
   565→
   566→  const tidStr = String(tid);
   567→  const team = results.find(t =>
   568→    String(t.tid) === tidStr || String(t.id) === tidStr
   569→  );
   570→
   571→  if (!team) {
   572→    console.warn(`[rtnStatsService] Team tid=${tid} not found in ranking results`);
   573→    return null;
   574→  }
   575→
   576→  return {
   577→    rank: team.rank ? String(team.rank) : null,
   578→    ave: team.ave ? String(team.ave) : null,
   579→    high: team.high ? String(team.high) : null,
   580→    rqs: team.rqs != null ? String(team.rqs) : null,
   581→    conference: team.conference || team.conf || null,
   582→    region: team.region || null,
   583→    division: team.division || team.div || null,
   584→  };
   585→}
   586→
   587→/**
   588→ * Normalize all raw fetch results for a team into the Firebase schema.
   589→ * Takes the results array from rateLimitedFetch and produces the full stats object.
   590→ *
   591→ * @param {Array<{label: string, data: Object|null, status: string}>} fetchResults
   592→ * @param {string} gender - "mens" or "womens"
   593→ * @param {number|string} tid - RTN team ID
   594→ * @returns {Object} { normalized: {...}, endpointStatus: {...} }
   595→ */
   596→function normalizeAllResults(fetchResults, gender, tid) {
   597→  const normalized = {};
   598→  const endpointStatus = {};
   599→
   600→  for (const result of fetchResults) {
   601→    endpointStatus[result.label] = result.status;
   602→
   603→    if (result.status !== 'ok' || !result.data) continue;
   604→
   605→    switch (result.label) {
   606→      case 'teamRanking':
   607→        normalized.teamRanking = normalizeTeamRanking(result.data, gender, tid);
   608→        break;
   609→      case 'consistency':
   610→        normalized.consistency = normalizeConsistency(result.data, gender);
   611→        break;
   612→      case 'mvp':
   613→        normalized.mvp = normalizeMVP(result.data, gender);
   614→        break;
   615→      case 'topScores':
   616→        normalized.topScores = normalizeTopScores(result.data, gender);
   617→        break;
   618→      case 'lineup':
   619→        normalized.lineup = normalizeLineup(result.data, gender);
   620→        break;
   621→      case 'individualHighs':
   622→        normalized.individualHighs = normalizeIndividualHighs(result.data, gender);
   623→        break;
   624→      case 'individualAverages':
   625→        normalized.individualAverages = normalizeIndividualAverages(result.data, gender);
   626→        break;
   627→    }
   628→  }
   629→
   630→  return { normalized, endpointStatus };
   631→}
